// Get all rows fetched from Google Sheets
const allRows = $input.all();

// Pick the last row (the newest form response)
const latestLead = allRows[allRows.length - 1].json;

// Extract and parse the bill number safely
const rawBill = latestLead["Monthly Electricity Bill (EGP)"];
const parsedBill = typeof rawBill === 'number' 
  ? rawBill 
  : Number(String(rawBill || '').replace(/[^0-9.]/g, ''));

return {
  json: {
    lead_name: latestLead["Full Name"] || "Client",
    lead_phone: latestLead["Phone Number"] || "",
    lead_sector: latestLead["Sector / System type"] || "Residential",
    monthly_bill_egp: parsedBill || 2000,
    location: latestLead["City / Governorate"] || "Egypt"
  }
};

