// Extract and sanitize LLM output
const inputData = $input.first().json;

function cleanScript(text) {
  if (!text) return "";
  return text
    .replace(/\\n/g, ' ')                  // Remove literal newline strings
    .replace(/[\r\n]+/g, ' ')              // Remove actual multiline breaks
    .replace(/^\d+\.\s*/gm, '')            // Remove list numbers like "1. "
    .replace(/[#*_-]/g, '')                // Remove markdown syntax
    .replace(/\s+/g, ' ')                  // Collapse double spaces
    .trim();
}

const rawScript = inputData.video_script || inputData.text || "";

return {
  json: {
    video_subject: inputData.video_subject || "Solar Feasibility Report",
    video_script: cleanScript(rawScript),
    video_terms: "solar panels, rooftop solar energy, clean energy, house roof"
  }
};
